{"command": "create", "path": "/app/workspace/extract_receipts.py", "file_text": "import os
import re
import json
from datetime import date as DateType
from decimal import Decimal

import pytesseract
from PIL import Image
from openpyxl import Workbook


IMG_DIR = '/app/workspace/dataset/img'
OUTPUT = '/app/workspace/stat_ocr.xlsx'


TOTAL_PRIORITY = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE',
     'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
]

EXCLUSIONS = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST',
              'DISCOUNT', 'CHANGE', 'CASH TENDERED']

NUMBER_RE = re.compile(r'(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})')
# For the "number on next line" fallback.
LOOSE_NUMBER_RE = re.compile(r'(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}|\d+)')


def ocr_text(img, psm):
    try:
        return pytesseract.image_to_string(img, config=f'--psm {psm}')
    except Exception:
        return ''


def normalize_for_match(line):
    """Normalize punctuation to spaces for substring keyword matching."""
    up = line.upper()
    up = re.sub(r'[^A-Z0-9. ]', ' ', up)
    up = re.sub(r'\s+', ' ', up).strip()
    return up


def is_excluded(line):
    norm = normalize_for_match(line)
    stripped = re.sub(r'^[\d. ]+', '', norm).strip()
    for exc in sorted(EXCLUSIONS, key=len, reverse=True):
        if stripped.startswith(exc):
            after = stripped[len(exc):len(exc) + 1]
            if after == '' or not after.isalpha():
                return True
    return False


def extract_number(line):
    nums = NUMBER_RE.findall(line)
    if nums:
        return nums[-1].replace(',', '')
    return None


def extract_number_fallback(line):
    nums = LOOSE_NUMBER_RE.findall(line)
    if nums:
        return nums[-1].replace(',', '')
    return None


def extract_total(text):
    """Return monetary string (e.g. '47.70') or None."""
    lines = text.split('\n')
    for keywords in TOTAL_PRIORITY:
        candidates = []
        for i, line in enumerate(lines):
            if is_excluded(line):
                continue
            norm = normalize_for_match(line)
            matched_kw = None
            for kw in sorted(keywords, key=len, reverse=True):
                if kw in norm:
                    matched_kw = kw
                    break
            if matched_kw is None:
                continue
            val = extract_number(line)
            if val is None and i + 1 < len(lines):
                nxt = lines[i + 1]
                if not is_excluded(nxt):
                    val = extract_number(nxt)
                    if val is None:
                        v2 = extract_number_fallback(nxt)
                        if v2 and '.' not in v2:
                            # Treat trailing integer as integer dollars.
                            v2 = f"{int(v2)}.00"
                        val = v2
            if val is not None:
                candidates.append((i, val))
        if candidates:
            _, val = candidates[-1]
            try:
                return f"{Decimal(val):.2f}"
            except Exception:
                return None
    return None


DATE_RES = [
    re.compile(r'\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{4})\b'),
    re.compile(r'\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2})\b'),
]


def try_date(d, m, y):
    if len(str(y)) == 2:
        y = 2000 + int(y)
    else:
        y = int(y)
    d, m = int(d), int(m)
    for day, mo in [(d, m), (m, d)]:
        try:
            return DateType(y, mo, day).isoformat()
        except ValueError:
            continue
    return None


def extract_date(text):
    """Return ISO date or None. Prefer DD-first (Malaysian) interpretation."""
    for rex in DATE_RES:
        for m in rex.finditer(text):
            d, mo, y = m.group(1), m.group(2), m.group(3)
            if len(y) == 2:
                yy = 2000 + int(y)
            else:
                yy = int(y)
            di, mi = int(d), int(mo)
            # Prefer DD/MM/YYYY (Malaysian locale).
            try:
                return DateType(yy, mi, di).isoformat()
            except ValueError:
                try:
                    return DateType(yy, di, mi).isoformat()
                except ValueError:
                    continue
    return None


def process_image(path):
    img = Image.open(path)
    texts = {psm: ocr_text(img, psm) for psm in (6, 4, 11)}

    # Date: try PSM 6 first, then others.
    date_val = None
    for psm in (6, 4, 11):
        date_val = extract_date(texts[psm])
        if date_val:
            break

    # Total: run per-PSM, prefer the match with highest priority.
    # Track priority index per candidate.
    best = None  # (priority_idx, line_idx, psm_order, value)
    for order, psm in enumerate((6, 4, 11)):
        text = texts[psm]
        lines = text.split('\n')
        for pi, keywords in enumerate(TOTAL_PRIORITY):
            found_in_pass = []
            for i, line in enumerate(lines):
                if is_excluded(line):
                    continue
                norm = normalize_for_match(line)
                matched = any(kw in norm for kw in keywords)
                if not matched:
                    continue
                val = extract_number(line)
                if val is None and i + 1 < len(lines):
                    nxt = lines[i + 1]
                    if not is_excluded(nxt):
                        val = extract_number(nxt)
                if val is not None:
                    found_in_pass.append((i, val))
            if found_in_pass:
                # Within a single OCR pass, prefer the LAST match
                # (handles "Total (Inclusive GST)" ... "TOTAL" rounding).
                i_last, val_last = found_in_pass[-1]
                cand = (pi, order, -i_last, val_last)
                if best is None or (cand[0], cand[1]) < (best[0], best[1]):
                    best = cand
                break  # move to the next PSM

    total_val = None
    if best is not None:
        raw = best[3]
        try:
            total_val = f"{Decimal(raw):.2f}"
        except Exception:
