    files = sorted(os.listdir(IMG_DIR))
    for fn in files:
        if not fn.lower().endswith(('.jpg', '.jpeg', '.png')):
            continue
        path = os.path.join(IMG_DIR, fn)
        date_val, total_val = process_image(path)
        rows.append((fn, date_val, total_val))
        print(f"{fn}: date={date_val}, total={total_val}")

