            continue
        cand = (pi, order, val)
        if best is None or (cand[0], cand[1]) < (best[0], best[1]):
            best = cand

    total_val = best[2] if best else None
    return date_val, total_val


def main():
    rows = []
    files = sorted(os.listdir(IMG_DIR))
    for fn in files:
        if not fn.lower().endswith(('.jpg', '.jpeg', '.png')):
