        if candidates:
            _, val = candidates[-1]
            try:
                return f"{Decimal(val):.2f}", priority_idx
            except Exception:
                return None, None
    return None, None


DATE_RES = [
    re.compile(r'\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{4})\b'),
    re.compile(r'\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2})\b'),
]


def extract_date(text):
    for rex in DATE_RES:
        for m in rex.finditer(text):
            d, mo, y = m.group(1), m.group(2), m.group(3)
            yy = 2000 + int(y) if len(y) == 2 else int(y)
            di, mi = int(d), int(mo)
            # Prefer DD/MM/YYYY (Malaysian locale), fall back to swap.
            try:
                return DateType(yy, mi, di).isoformat()
            except ValueError:
                try:
                    return DateType(yy, di, mi).isoformat()
                except ValueError:
                    continue
    return None


def process_image(path):
    img = Image.open(path)
    texts = {}
    for psm in (6, 4, 11):
        try:
            texts[psm] = pytesseract.image_to_string(img, config=f'--psm {psm}')
        except Exception:
            texts[psm] = ''

    # DATE: pick first valid date across passes (preferring PSM 6).
    date_val = None
    for psm in (6, 4, 11):
        d = extract_date(texts[psm])
        if d:
            date_val = d
            break

    # TOTAL: run extraction per PSM; pick the result with the highest
    # (= lowest-indexed) priority; tie-break by PSM preference order.
    best = None  # (priority_idx, psm_order, value)
    for order, psm in enumerate((6, 4, 11)):
        val, pi = extract_total(texts[psm])
        if val is None:
            continue
        cand = (pi, order, val)
        if best is None or (cand[0], cand[1]) < (best[0], best[1]):
            best = cand

    total_val = best[2] if best else None
    return date_val, total_val


def main():
    rows = []
    files = sorted(os.listdir(IMG_DIR))
    for fn in files:
        if not fn.lower().endswith(('.jpg', '.jpeg', '.png')):
            continue
        path = os.path.join(IMG_DIR, fn)
        date_val, total_val = process_image(path)
        rows.append((fn, date_val, total_val))
        print(f"{fn}: date={date_val}, total={total_val}")

    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for r in rows:
        ws.append(list(r))
    wb.save(OUTPUT)


if __name__ == '__main__':
    main()
